let parsed;

try {
  parsed = typeof $json.output === "string"
    ? JSON.parse($json.output)
    : $json.output;
} catch (e) {
  parsed = {
    intent: "unknown",
    product_mentioned: "unknown",
    product_id: "unknown",
    summary: "Parsing failed"
  };
}

return parsed;

return items.map(item => {
  const data = item.json;

  let score = 0;

  // Intent-based scoring
  switch (data.intent) {
    case "price_inquiry":
      score += 5;
      break;
    case "availability_inquiry":
      score += 4;
      break;
    case "product_question":
      score += 3;
      break;
    case "general_message":
      score += 1;
      break;
    default:
      score += 0;
  }

  return {
    json: {
      ...data,
      lead_score: score
    }
  };
});

